"""Generator primitives: the immutable input snapshot and generated file records."""

from __future__ import annotations

import ipaddress
from dataclasses import dataclass, field
from pathlib import Path
from typing import Any

from jinja2 import Environment, FileSystemLoader, StrictUndefined
from sqlalchemy import select
from sqlalchemy.orm import Session

from phonix import __version__
from phonix.core import settings as st
from phonix.core.models import (
    AmiUser,
    Application,
    BusinessHours,
    CallGroup,
    ConferenceRoom,
    IvrMenu,
    MediaFile,
    Phone,
    Provider,
)

TEMPLATES = Path(__file__).parent / "templates"
DATA = Path(__file__).parent / "data"

HEADER = "; Generated by PhonixPBX {version} - do not edit, changes will be overwritten.\n"


@dataclass(frozen=True)
class Facts:
    """Runtime facts that are not stored in the database (collected at apply time)."""

    lan_ip: str = "127.0.0.1"
    lan_prefix: int = 8
    data_dir: str = "/data"
    version: str = __version__
    # phonix.services.platform.kind(): appliance, lxc, oci or dev
    platform: str = "appliance"

    @property
    def lan_network(self) -> str:
        net = ipaddress.ip_network(f"{self.lan_ip}/{self.lan_prefix}", strict=False)
        return str(net)


@dataclass(frozen=True)
class Secrets:
    ami_internal: str = "changeme"


@dataclass
class Snapshot:
    """Everything a generator may look at. Generators must not do any I/O."""

    system: st.SystemSettings
    network: st.NetworkSettings
    rtp: st.RtpSettings
    sip: st.SipSettings
    iax: st.IaxSettings
    voicemail: st.VoicemailSettings
    email: st.EmailSettings
    features: st.FeatureSettings
    media: st.MediaSettings
    firewall: st.FirewallSettings
    phones: list[Phone]
    providers: list[Provider]
    callgroups: list[CallGroup]
    rooms: list[ConferenceRoom]
    applications: list[Application]
    ami_users: list[AmiUser]
    media_files: list[MediaFile]
    ivr_menus: list[IvrMenu] = field(default_factory=list)
    business_hours: list[BusinessHours] = field(default_factory=list)
    facts: Facts = field(default_factory=Facts)
    secrets: Secrets = field(default_factory=Secrets)

    # convenience views -----------------------------------------------------
    @property
    def active_phones(self) -> list[Phone]:
        return [p for p in self.phones if p.enabled]

    @property
    def active_providers(self) -> list[Provider]:
        return [p for p in self.providers if p.enabled]

    def phone(self, phone_id: int) -> Phone | None:
        return next((p for p in self.phones if p.id == phone_id), None)

    def provider(self, provider_id: int | None) -> Provider | None:
        return next((p for p in self.providers if p.id == provider_id), None)


def build_snapshot(session: Session, facts: Facts | None = None, secrets: Secrets | None = None) -> Snapshot:
    def ordered(model: Any, *order: Any) -> list[Any]:
        return list(session.scalars(select(model).order_by(*order)))

    phones = ordered(Phone, Phone.id)
    phones.sort(key=lambda p: (len(p.extension), p.extension))
    return Snapshot(
        system=st.load(session, st.SystemSettings),
        network=st.load(session, st.NetworkSettings),
        rtp=st.load(session, st.RtpSettings),
        sip=st.load(session, st.SipSettings),
        iax=st.load(session, st.IaxSettings),
        voicemail=st.load(session, st.VoicemailSettings),
        email=st.load(session, st.EmailSettings),
        features=st.load(session, st.FeatureSettings),
        media=st.load(session, st.MediaSettings),
        firewall=st.load(session, st.FirewallSettings),
        phones=phones,
        providers=ordered(Provider, Provider.id),
        callgroups=ordered(CallGroup, CallGroup.id),
        rooms=ordered(ConferenceRoom, ConferenceRoom.id),
        applications=ordered(Application, Application.id),
        ami_users=ordered(AmiUser, AmiUser.id),
        media_files=ordered(MediaFile, MediaFile.id),
        ivr_menus=ordered(IvrMenu, IvrMenu.id),
        business_hours=ordered(BusinessHours, BusinessHours.id),
        facts=facts or Facts(),
        secrets=secrets or Secrets(),
    )


@dataclass(frozen=True)
class GeneratedFile:
    """One output file.

    ``path`` is the absolute target path on the appliance. ``component`` names
    what has to be reloaded when the content changes (see services/apply.py).
    ``privileged`` files are installed by the root helper, all others are
    written directly by the (unprivileged) web process.
    """

    path: str
    content: str
    component: str
    mode: int = 0o640
    privileged: bool = False


def _cfg_escape(value: Any) -> str:
    """Escape for Asterisk config values (';' starts a comment)."""
    return str(value).replace(";", r"\;")


def _quote(value: Any) -> str:
    return '"' + str(value).replace('"', "") + '"'


_env: Environment | None = None


def env() -> Environment:
    global _env
    if _env is None:
        _env = Environment(
            loader=FileSystemLoader(str(TEMPLATES)),
            undefined=StrictUndefined,
            autoescape=False,  # noqa: S701 - generating config files, not HTML
            trim_blocks=True,
            lstrip_blocks=True,
            keep_trailing_newline=True,
        )
        _env.filters["cfg"] = _cfg_escape
        _env.filters["quote"] = _quote
        _env.filters["yesno"] = lambda b: "yes" if b else "no"
        _env.filters["msmtp_quote"] = lambda s: '"' + str(s).replace("\\", "\\\\").replace('"', '\\"') + '"'
        _env.globals["header"] = lambda: HEADER.format(version=__version__)
    return _env


def render(template: str, **ctx: Any) -> str:
    return env().get_template(template).render(**ctx)
